const routine=[
 ['Аудирование и пересказ','Сначала слушайте без субтитров. Затем проверьте детали по транскрипту и перескажите вслух.'],
 ['Разговор','Обсудите тему с собеседником и ответьте на уточняющие вопросы.'],
 ['Чтение и грамматика','Разберите текст и проверьте повторяющуюся ошибку по Murphy, English Grammar in Use.'],
 ['Текст и правка','Напишите короткий текст, запросите обратную связь и внесите правки.'],
 ['Разговор или задание на время','Выполните контрольное задание недели и запишите результат.']
];
export function englishPlanWeek(index){
 const [dates,title,result,instructions,keys]=weeks[index];
 const start=new Date(Date.UTC(2026,10,16+7*index)).toISOString().slice(0,10);
 const light=index>=6&&index<=9;
 const days=index===28?[0]:light?[0,1,3]:[0,1,2,3,4];
 const refs=[...new Set([...keys,'review'])].map(key=>materials[key]);
 const tasks=days.map(offset=>({
  offset, title:index===28?'Английский · итоги и летний приоритет':'Английский · '+routine[offset][0],
  minutes:index===28?30:light?25:45,
  note:[index===28?instructions:routine[offset][1],instructions,'Первые 5–10 минут — карточки. Возьмите 3–5 выражений, составьте свои примеры и используйте их снова.',...refs.map(([label,url])=>label+' '+url)].join('\n')
 }));
 tasks.push(...(index===1||index===19?[{offset:index===1?6:2,title:index===1?'Английский · завершить диагностику B2':'Английский · решение о переходе к C1',minutes:20,note:result+' '+instructions}]:[]));
 return {start,title:dates+' · '+title,why:instructions,result,gate:result,refs,tasks:tasks.sort((a,b)=>a.offset-b.offset)};
}
